{
  "command": "cd \"/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes_r2/sonnet/slot1\" && find papers ceridwen -iname '*.pdf' 2>/dev/null | rg -i \"noll|kriek|conroy|calzetti|dust|atten\" | head; rg -il \"Kriek\" papers/README.md; which pdftotext",
  "description": "Locate local dust papers and pdftotext"
}

{
  "query": "select:WebFetch,WebSearch",
  "max_results": 2
}

{
  "url": "arxiv.org/abs/0903.5302",
  "prompt": "What is the title, and what is the Noll et al. 2009 modified Calzetti attenuation law: the equation with the Drude UV bump D_lambda (E_b, central wavelength, FWHM) and the power-law slope delta? Give the formulas and parameter values exactly as in the paper."
}

{
  "url": "arxiv.org/abs/1308.6270",
  "prompt": "What does Kriek & Conroy 2013 say about the UV dust bump and its Eq. 2 (Noll-style attenuation curve, Drude profile, E_b, delta)? Give formulas and the E_b-delta relation found."
}

{
  "url": "https://arxiv.org/abs/0903.5302",
  "prompt": "What is the title, and what is the Noll et al. 2009 modified Calzetti attenuation law: the equation with the Drude UV bump D_lambda (E_b, central wavelength, FWHM) and the power-law slope delta? Give the formulas and parameter values exactly as in the paper."
}

{
  "url": "https://arxiv.org/abs/1308.6270",
  "prompt": "What does Kriek & Conroy 2013 say about the UV dust bump and its Eq. 2 (Noll-style attenuation curve, Drude profile, E_b, delta)? Give formulas and the E_b-delta relation found."
}

{
  "query": "Noll 2009 \"Analysis of galaxy spectral energy distributions from far-UV to far-IR with CIGALE\" arXiv dust attenuation UV bump",
  "mode": "standard"
}

{
  "query": "Kriek Conroy 2013 \"The Dust Attenuation Law in Distant Galaxies\" arXiv UV bump delta",
  "mode": "standard"
}

{
  "url": "https://ar5iv.arxiv.org/html/0909.5439",
  "prompt": "Find the section where the attenuation law is modified with a UV bump (Drude profile) and a power-law slope delta. Quote the equations exactly: the Drude profile D_lambda definition (E_b, lambda_0 central wavelength, gamma/FWHM), the modified Calzetti formula with (lambda/lambda_V)^delta, and the stated parameter values (central wavelength, FWHM, bump amplitude range, delta range)."
}

{
  "url": "https://ar5iv.arxiv.org/html/1308.1099",
  "prompt": "Quote Eq. 1 and Eq. 2 exactly (attenuation curve with Drude bump D(lambda), E_b, delta, Calzetti k(lambda)), the stated bump central wavelength and width, and the E_b vs delta relation found, including its fitted formula."
}
